using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioCheckerMapValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static MashBoxStudioViewport view;static AnimationStudioWindow host;static Material original;static int checks;static double ready;
 static string PathFor(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+name));static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{var globalType=Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineGlobalSettings, Unity.RenderPipelines.HighDefinition.Runtime");globalType.GetMethod("Ensure",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{true});var pipeline=(RenderPipelineAsset)ScriptableObject.CreateInstance(Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineAsset, Unity.RenderPipelines.HighDefinition.Runtime"));AssetDatabase.CreateAsset(pipeline,AssetDatabase.GenerateUniqueAssetPath("Assets/StudioShaderValidationPipeline.asset"));GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;Check(GraphicsSettings.currentRenderPipeline&&GraphicsSettings.currentRenderPipeline.GetType().Name.Contains("HDRenderPipeline"),"HDRP pipeline active");var shader=AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath("409bba92b9fbb904cbfd7cf58b9531a6"));Check(shader&&!ShaderUtil.ShaderHasError(shader),"Graph imports and compiles");defaultAsset=StudioMeshMaterialPreview.DefaultMaterial;originalColor=defaultAsset.GetColor("_BaseColor");defaultAsset.SetColor("_BaseColor",new Color(.8f,.1f,.1f));doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);original=new Material(GraphicsSettings.currentRenderPipeline.defaultMaterial);doc.nodes.Add(new StudioModelDocument.Node{name="Studio default",mesh=mesh,materials=new[]{defaultAsset},cutPolygons=polygons,cutTriangles=mesh.triangles});doc.lighting.studioLights=true;doc.lighting.ground=false;doc.lighting.exposure=0;AnimationStudioWindow.Open();host=Resources.FindObjectsOfTypeAll<AnimationStudioWindow>().First();typeof(AnimationStudioWindow).GetMethod("SwitchStudioMode",F).Invoke(host,new object[]{true});typeof(AnimationStudioWindow).GetMethod("LoadStudioModel",F).Invoke(host,new object[]{doc});editor=host.ToolbarModelEditor;editor.SetDisplayMode(true,false);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().First(v=>v.Studio==host);view.position=new Rect(60,60,800,650);view.LookAtDirect(Vector3.zero,Quaternion.Euler(20,35,0),2);ready=EditorApplication.timeSinceStartup+3;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static int blackPhase;static string diagnostics="";static Material defaultAsset;static Color originalColor;
 static Color32[] Native(string file){var field=typeof(MashBoxStudioViewport).GetField("cachedScene",F);var rt=field.GetValue(view) as RenderTexture;if(!rt||!rt.IsCreated())return null;var previous=RenderTexture.active;try{RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(PathFor(file),image.EncodeToPNG());var pixels=image.GetPixels32();Object.DestroyImmediate(image);return pixels;}finally{RenderTexture.active=previous;}}
 static StudioToolbarCheckerMap button;static Color32[] neutral;
 static int Variation(Color32[] values)=>values.Select(c=>(c.r/16)*256+(c.g/16)*16+c.b/16).Distinct().Count();
 static void Tick(){if(EditorApplication.timeSinceStartup<ready)return;try{var pixels=Native("checker-map-"+blackPhase+".png");if(pixels==null){view.Repaint();ready=EditorApplication.timeSinceStartup+.5;return;}
 if(blackPhase==0){editor.SetCheckerMap(false);editor.EditLighting(s=>s.studioLights=false);editor.SetDisplayMode(true,false);blackPhase=1;}
 else if(blackPhase==1){neutral=pixels;var target=StudioMeshMaterialPreview.CheckerMaterial;Check(target&&target.name=="MashBoxStudio_Checkerboard","Checker target missing");Check(target.HasTexture("_CheckerboardMap")&&target.GetTexture("_CheckerboardMap")&&target.shader.name=="MGShaders/HDRP/Lit/MashBoxStudio_Default_Modeling_CheckerMap_Shader","Checker asset setup missing");button=new StudioToolbarCheckerMap{containerWindow=view};view.rootVisualElement.Add(button);Check(button.icon&&button.tooltip=="Checker Map","Checker toolbar button/icon missing");button.value=true;Check(editor.CheckerMap,"Toolbar event did not enable checker override");blackPhase=2;}
 else if(blackPhase==2){var material=editor.Transforms[0].GetComponent<Renderer>().sharedMaterial;Check(material.shader.name=="MashBox/Studio/Preview","Camera checker does not use computed lighting");Check(material.GetTexture("_MainTex")==StudioMeshMaterialPreview.CheckerMaterial.GetTexture("_CheckerboardMap"),"Camera checker did not bind target UV texture");Check(Variation(pixels)>25&&pixels.Zip(neutral,(a,b)=>a.Equals(b)?0:1).Sum()>1000,"Checker texture not visible in native camera output");Check(doc.nodes[0].materials[0]==defaultAsset&&!editor.ToolbarTextures,"Checker changed source or material toggle");button.value=false;Check(!editor.CheckerMap,"Toolbar did not disable checker");blackPhase=3;}
 else if(blackPhase==3){Check(pixels.Length==neutral.Length&&pixels.Zip(neutral,(a,b)=>a.Equals(b)?1:0).Sum()>pixels.Length*.98,"Checker OFF failed to restore neutral appearance");editor.EditLighting(s=>s.studioLights=true);button.value=true;blackPhase=4;}
 else if(blackPhase==4){view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);blackPhase=5;}
 else if(blackPhase==5){var material=editor.Transforms[0].GetComponent<Renderer>().sharedMaterial;Check(material.shader==StudioMeshMaterialPreview.CheckerMaterial.shader&&material.GetTexture("_CheckerboardMap")==StudioMeshMaterialPreview.CheckerMaterial.GetTexture("_CheckerboardMap"),"Studio Lights did not use target checker shader/settings");Check(Variation(pixels)>25,"Checker texture not visible in native Studio Lights output");Check(StudioPreferenceStore.GetFloat("Model.CheckerMap",0)==1,"Checker preference was not saved");Check(doc.nodes[0].materials[0]==defaultAsset,"Checker override modified object material assignment");button.value=false;button.RemoveFromHierarchy();EditorApplication.update-=Tick;Finish("PASS "+checks+" checker toolbar, texture binding, native Camera/Studio output, restore and preference checks");return;}
 ready=EditorApplication.timeSinceStartup+1;view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);
 }catch(Exception e){EditorApplication.update-=Tick;Finish(e.ToString());}}
 sealed class MaterialScope:IDisposable{internal Material Value;internal MaterialScope(Shader s){Value=new Material(s);}public void Dispose(){Object.DestroyImmediate(Value);}}
 static void Finish(string result){EditorApplication.update-=Tick;if(defaultAsset)defaultAsset.SetColor("_BaseColor",originalColor);File.WriteAllText(PathFor("checker-map-result.txt"),result);EditorApplication.delayCall+=()=>{if(view)view.Close();if(host)Object.DestroyImmediate(host);double end=EditorApplication.timeSinceStartup+1;void Exit(){if(EditorApplication.timeSinceStartup<end)return;EditorApplication.update-=Exit;EditorApplication.Exit(result.StartsWith("PASS")?0:1);}EditorApplication.update+=Exit;};}
